function renderTeoria(el){
  const sec=[
   [T('El sistema complejo adaptativo','The complex adaptive system'),T('Un sistema complejo adaptativo está formado por agentes heterogéneos que interactúan localmente, aprenden y se adaptan; de esas interacciones emergen patrones que ningún agente diseñó (Holland, 1995). Un viñedo lo es: productores, semillas, suelo, agua, saberes, instituciones y mercados que se retroalimentan en cada ciclo. García (2006) propone estudiarlos como totalidades organizadas cuyos elementos no son separables, y Morin (1990), como lo que está «tejido junto» (complexus), raíz del nombre de esta línea de la suite.','A complex adaptive system consists of heterogeneous agents that interact locally, learn and adapt; patterns no agent designed emerge from those interactions (Holland, 1995). A vineyard is one: farmers, seeds, soil, water, knowledge, institutions and markets feeding back each cycle. García (2006) proposes studying them as organised wholes whose elements cannot be separated, and Morin (1990) as what is “woven together” (complexus), the root of this suite line’s name.')],
   [T('Orden, caos y resiliencia','Order, chaos and resilience'),T('En la tesis, los fundamentos del modelo interactúan de manera caórdica, entre el orden y el caos (Prigogine, 1983; Hock, 1999). Holling (2001) y Gunderson y Holling (2002) describen los ciclos adaptativos y la panarquía: crecimiento, conservación, liberación y reorganización a varias escalas. Las heladas tardías, el granizo y las olas de calor que alteran la brotación y la maduración son ejemplos de ese entorno.','In the thesis, the model’s foundations interact chaordically, between order and chaos (Prigogine, 1983; Hock, 1999). Holling (2001) and Gunderson and Holling (2002) describe adaptive cycles and panarchy: growth, conservation, release and reorganisation across scales. The climate disturbances shifting the sowing date are examples of that environment.')],
   [T('Clima vitícola y fenología','Viticultural climate and phenology'),T('La vid responde al calor acumulado en su temporada: Amerine y Winkler (1944) clasificaron las regiones vitícolas por grados día sobre 10 °C de abril a octubre; Huglin (1978) añadió el peso de las temperaturas máximas, y Tonietto y Carbonneau (2004) integraron el frescor de las noches de maduración en una clasificación multicriterio. El ciclo anual se describe con los estadios fenológicos de la escala BBCH para la vid (Lorenz et al., 1995), que ordenan el cuestionario base de Ratio Viña. En climas sin invierno marcado, como buena parte del trópico mexicano, la vid puede no entrar en reposo y estos índices se leen con cautela.','The vine responds to heat accumulated over its season: Amerine and Winkler (1944) classified wine regions by degree days above 10 °C from April to October; Huglin (1978) added the weight of maximum temperatures, and Tonietto and Carbonneau (2004) integrated ripening-night coolness into a multicriteria classification. The annual cycle is described with the BBCH phenological stages for grapevine (Lorenz et al., 1995), which order the Ratio Viña baseline questionnaire. In climates without a marked winter, as in much of tropical Mexico, the vine may not go dormant and these indices are read with caution.')],
   [T('El Stack de conocimiento local','The local knowledge stack'),T('El Stack organiza el conocimiento agrícola en capas interdependientes con cuatro rasgos: multidimensionalidad, jerarquización, interdisciplinariedad y aplicabilidad (Díaz-José et al., 2026). Combina conocimiento tácito y explícito, que se convierten uno en otro en la creación de conocimiento (Nonaka y Takeuchi, 1995), y la memoria biocultural de las comunidades (Toledo y Barrera-Bassols, 2008).','The Stack organises farming knowledge in interdependent layers with four traits: multidimensionality, hierarchy, interdisciplinarity and applicability (Díaz-José et al., 2026). It combines tacit and explicit knowledge, which convert into each other as knowledge is created (Nonaka & Takeuchi, 1995), and communities’ biocultural memory (Toledo & Barrera-Bassols, 2008).')],
   [T('Gestión Estratégica Integrada y racionalidad ambiental','Integrated Strategic Management and environmental rationality'),T('El modelo de la tesis integra fundamentos socioeconómicos, ambientales y turístico-ecotecnológicos con enfoques participativo, sostenible y de sistemas complejos, en cuatro fases y nueve pasos (Mojica Zárate, 2017). Se apoya en la racionalidad ambiental de Leff (1994, 2004), que pide reconocer los saberes locales frente a la racionalidad económica dominante, y en el marco de sistemas socioecológicos de Ostrom (2009).','The thesis model integrates socio-economic, environmental and tourism–eco-technological foundations with participatory, sustainable and complex-systems approaches, in four phases and nine steps (Mojica Zárate, 2017). It draws on Leff’s (1994, 2004) environmental rationality, which calls for recognising local knowledge against dominant economic rationality, and on Ostrom’s (2009) social-ecological systems framework.')],
   [T('Redes y estadística','Networks and statistics'),T('La centralidad de grado, cercanía e intermediación (Freeman, 1978; algoritmo de Brandes, 2001) identifica a quién articula el sistema; el agrupamiento y el camino medio caracterizan los «mundos pequeños» (Watts y Strogatz, 1998); la modularidad mide la estructura de comunidades (Newman y Girvan, 2004; Newman, 2006), que aquí se detectan con el método de Louvain (Blondel et al., 2008). La correlación φ entre elementos es la de Pearson sobre su incidencia en las actividades. El cladograma agrupa a los elementos por su distancia en la red (camino más corto con longitud 1/peso) con el enlace simple o del vecino más cercano (Sneath, 1957; Sokal y Sneath, 1963); la correlación cofenética indica qué tan fiel es el árbol a esas distancias (Sokal y Rohlf, 1962).','Degree, closeness and betweenness centrality (Freeman, 1978; Brandes’ algorithm, 2001) identify who holds the system together; clustering and mean path characterise “small worlds” (Watts & Strogatz, 1998); modularity measures community structure (Newman & Girvan, 2004; Newman, 2006), detected here with the Louvain method (Blondel et al., 2008). The φ correlation between elements is Pearson’s on their incidence across activities. The cladogram groups elements by network distance (shortest path with length 1/weight) using single or nearest-neighbour linkage (Sneath, 1957; Sokal & Sneath, 1963); the cophenetic correlation shows how faithfully the tree keeps those distances (Sokal & Rohlf, 1962).')],
   [T('Regeneración y riesgo','Regeneration and risk'),T('Un sistema regenerativo no solo se mantiene: mejora con cada ciclo el suelo, el agua y la biodiversidad de los que depende. Las definiciones de agricultura regenerativa combinan procesos (mínima perturbación del suelo, suelo cubierto, diversidad, raíces vivas, integración animal, menos insumos de síntesis) y resultados (más materia orgánica, mejor ciclo del agua, más biodiversidad) (Newton et al., 2020; Schreefel et al., 2020); los cuatro primeros procesos son los principios de salud del suelo del USDA-NRCS. Ratio Viña los mide con ocho perillas ordinales de 0 a 4, sugeridas a partir de las actividades del Stack, y con una línea base para seguir la trayectoria del sistema. El riesgo se entiende como en el IPCC (2014): resulta de la amenaza, la exposición y la vulnerabilidad; se estima con una matriz de probabilidad por impacto de 5 × 5 (IEC 31010:2019) dentro del proceso de gestión de ISO 31000:2018. La capacidad adaptativa —regeneración, diversificación, conocimiento técnico e integración institucional— reduce la vulnerabilidad, y conecta el riesgo con la resiliencia de los ciclos adaptativos (Holling, 2001).','A regenerative system does not merely maintain itself: each cycle it improves the soil, water and biodiversity it depends on. Definitions of regenerative agriculture combine processes (minimal soil disturbance, soil cover, diversity, living roots, livestock integration, fewer synthetic inputs) and outcomes (more organic matter, better water cycling, more biodiversity) (Newton et al., 2020; Schreefel et al., 2020); the first four processes are the USDA-NRCS soil health principles. Ratio Viña measures them with eight ordinal 0–4 knobs, suggested from the Stack activities, and with a baseline to follow the system’s trajectory. Risk is understood as in the IPCC (2014): it results from hazard, exposure and vulnerability; it is estimated with a 5 × 5 likelihood-by-impact matrix (IEC 31010:2019) within the ISO 31000:2018 management process. Adaptive capacity —regeneration, diversification, technical knowledge and institutional integration— reduces vulnerability and links risk with the resilience of adaptive cycles (Holling, 2001).')],
   [T('Prospectiva y futuribles','Foresight and futuribles'),T('La prospectiva parte de que el futuro no está escrito: es múltiple e incierto, y se construye con las decisiones de hoy. De Jouvenel (1964) llamó «futuribles» a los futuros posibles, y Godet (2007; Godet y Durance, 2011) sistematizó la prospectiva estratégica con el análisis estructural (MICMAC), el juego de actores (MACTOR) y los escenarios. En la tesis, la prospectiva es uno de los siete principios del procedimiento: el estado deseado se fija con una línea base y un horizonte futurible, el plan estratégico distingue desafíos, riesgos, potencialidades y limitaciones, y la ejecución se sigue con una línea prospectiva y escenarios de los indicadores estratégicos (Mojica Zárate, 2017). Ratio Viña lleva esta idea a la unidad productiva con tres escenarios exploratorios a 2, 5 y 10 años: deseable, tendencial y no deseado. No son pronósticos, sino futuros posibles construidos con supuestos explícitos. El clima entra con la tasa de calentamiento del IPCC (2018) y la pérdida de rendimiento por grado de Zhao et al. (2017); la adopción de las innovaciones del Stack sigue la curva en S de la difusión (Rogers, 2003); los precios, los costos y la pérdida de mano de obra en el campo son supuestos editables. En un sistema complejo adaptativo el futuro emerge de las interacciones y puede cambiar de rumbo tras una perturbación (Holling, 2001): por eso los escenarios sirven para conversar y decidir, no para predecir.','Foresight starts from the idea that the future is not written: it is multiple and uncertain, and is built by today’s decisions. De Jouvenel (1964) called possible futures “futuribles”, and Godet (2007; Godet & Durance, 2011) systematised strategic foresight with structural analysis (MICMAC), actor analysis (MACTOR) and scenarios. In the thesis, foresight is one of the seven principles of the procedure: the desired state is set with a baseline and a futurible horizon, the strategic plan distinguishes challenges, risks, potentials and limitations, and implementation is followed with a foresight line and scenarios of the strategic indicators (Mojica Zárate, 2017). Ratio Viña brings this idea to the farm with three exploratory scenarios at 2, 5 and 10 years: desirable, trend and undesired. They are not forecasts but possible futures built on explicit assumptions. Climate enters with the IPCC (2018) warming rate and the yield loss per degree of Zhao et al. (2017); adoption of the Stack’s innovations follows the S-shaped diffusion curve (Rogers, 2003); prices, costs and the loss of farm labour are editable assumptions. In a complex adaptive system the future emerges from interactions and can change course after a disturbance (Holling, 2001): scenarios are for discussing and deciding, not for predicting.')],
   [T('Sostenibilidad, ODS y huella','Sustainability, SDGs and footprint'),T('La sostenibilidad se evalúa con indicadores por compartimento, en la tradición del marco MESMIS (Masera et al., 1999), y con el índice general de sostenibilidad de Sarandón (2002), que promedia las dimensiones económica, ecológica y sociocultural en escala de 0 a 4; y se relaciona con los 17 Objetivos de la Agenda 2030 (Naciones Unidas, 2015). La huella de carbono usa los factores por defecto del IPCC (2006, 2019) y los potenciales de calentamiento del AR6 (Forster et al., 2021). La huella ecológica en hectáreas globales (Wackernagel y Rees, 1996) requiere factores nacionales que no se incluyen.','Sustainability is assessed with compartment indicators in the tradition of the MESMIS framework (Masera et al., 1999) and with Sarandón’s (2002) general sustainability index, averaging economic, ecological and socio-cultural dimensions on a 0–4 scale; and related to the 17 Goals of the 2030 Agenda (United Nations, 2015). The carbon footprint uses IPCC default factors (2006, 2019) and AR6 warming potentials (Forster et al., 2021). The ecological footprint in global hectares (Wackernagel & Rees, 1996) needs national factors not included here.')]];
  const refs=[TESIS.cita].concat(TEORIA.map(t=>t.c)).concat(REF_EXTRA).sort((a,b)=>a.localeCompare(b,'es'));
  el.innerHTML = `${cabecera('teoria',T('Las ideas que sostienen a Ratio Viña: sistemas complejos adaptativos, saber local, gestión estratégica integrada, redes, regeneración, riesgo, prospectiva y sostenibilidad.','The ideas behind Ratio Viña: complex adaptive systems, local knowledge, integrated strategic management, networks, regeneration, risk, foresight and sustainability.'))}
  <div class="teoria">${sec.map((s,i)=>`<details ${i===0?'open':''}><summary>${s[0]}</summary><div class="tb"><p>${s[1]}</p></div></details>`).join('')}</div>
  <div class="card"><h2>${T('Referencias','References')}</h2><ol>${refs.map(r=>`<li>${esc(r)}</li>`).join('')}</ol></div>
  <div class="card"><h3>${T('Alcances y límites','Scope and limits')}</h3><ul>
   <li>${T('Todavía no existe un Stack publicado de la vid. El cuestionario base, los elementos y sus vínculos son una lectura de Ratio Viña ordenada por etapas BBCH; cada viñedo lo responde y amplía, y el atlas nacional solo agrega lo que respondieron los viñedos.','There is no published grapevine Stack yet. The baseline questionnaire, the elements and their links are a Ratio Viña reading ordered by BBCH stages; each vineyard answers and extends it, and the national atlas only combines what vineyards answered.')}</li>
   <li>${T('Los índices de clima se calculan con las temperaturas que captura el usuario; se desarrollaron para la viticultura templada.','Climate indices are computed from user-entered temperatures; they were developed for temperate viticulture.')}</li>
   <li>${T('Los vínculos entre actividades y elementos, los perfiles de impacto y la relación con los ODS son lecturas de Ratio Viña, marcadas y editables.','Activity–element links, impact profiles and the SDG mapping are Ratio Viña readings, flagged and editable.')}</li>
   <li>${T('La producción agrícola municipal del SIAP se integrará cuando su servicio de datos abiertos esté disponible.','SIAP municipal crop production will be added when its open-data service is available.')}</li></ul></div>
  ${siguiente('teoria')}`; }

/* ================= NAVEGACIÓN ================= */
/* La barra de avance y las marcas del menú cuentan SOLO lo que llenó el usuario (no las visitas, ni sugerencias, ni el ejemplo) */
function renderNav(){ $('#nav').innerHTML = BLOQUES.map(b=>{ const a=EJ?null:avance(b.id);
    return `<button class="${S.bloque===b.id?'act':''} ${a?'est-'+a.estado:''}" data-ir="${b.id}" ${a?`title="${esc(a.h+' / '+a.t+' · '+a.txt)}"`:''}><span class="n">${b.n}</span>${esc(tx(b.corto))}${a?`<i class="nav-est" aria-hidden="true"></i>`:''}</button>`; }).join('');
  const a=$('#nav .act'); if(a&&a.scrollIntoView) a.scrollIntoView({block:'nearest',inline:'center'});
  if(EJ){ $('#progTxt').textContent=T('Ejemplo publicado · no son tus datos','Published example · not your data'); $('#progFill').style.width='0%'; return; }
  const f=avanceTotal(), hechos=BLOQUES_LLENAR.filter(k=>avance(k).estado==='ok').length;
  $('#progTxt').textContent=T(`Llenado por ti: ${Math.round(100*f)} % · ${hechos} de ${BLOQUES_LLENAR.length} bloques completos`,`Filled in by you: ${Math.round(100*f)} % · ${hechos} of ${BLOQUES_LLENAR.length} blocks complete`); $('#progFill').style.width=(100*f)+'%'; }
function actualizarPill(){ const l=locSel(); $('#pillTxt').textContent=!S.vidDestino&&!S.vidVar&&!l?T('Viñedo nuevo · sin datos aún','New vineyard · no data yet'):[T('Vid','Grapevine'), destinoTexto(), S.vidVar].filter(Boolean).join(' · ')+(l?' · '+l[1]:''); }
function renderAyuda(){ $('#dlgAyuda').innerHTML=`<div class="dh"><h2>${T('Cómo usar Ratio Viña','How to use Ratio Viña')}</h2><button class="ibtn round" onclick="this.closest('dialog').close()" aria-label="×">✕</button></div>
  <div class="db"><ol><li>${T('<b>Avanza en orden</b>: cultivo, región, requerimientos, manejo, elementos y precio-valor.','<b>Move in order</b>: crop, region, requirements, management, elements and price-value.')}</li>
  <li>${T('En <b>Formulación</b> presiona <i>Tejer el sistema</i>; en <b>Tablero</b> ves la red y su estadística; en <b>Sostenibilidad</b>, los ODS y la huella.','In <b>Formulation</b> press <i>Weave the system</i>; <b>Dashboard</b> shows the network and its statistics; <b>Sustainability</b> shows SDGs and footprint.')}</li>
  <li>${T('Los signos <b>?</b> explican cada concepto y su escala de decisión.','The <b>?</b> signs explain each concept and its decision scale.')}</li>
  <li>${T('<b>Productor / Científico</b> cambia la vista; <b>ES / EN</b> el idioma; ☀/☾ el tema.','<b>Producer / Scientist</b> switches view; <b>ES / EN</b> language; ☀/☾ theme.')}</li>
  <li>${T('Tu trabajo se <b>guarda solo</b> en este navegador; usa <i>Informe → Guardar proyecto</i> para llevarlo a otro equipo.','Your work is <b>saved automatically</b> in this browser; use <i>Report → Save project</i> to move it.')}</li></ol></div>`; }
function render(){ document.documentElement.lang=LANG; $$('.langsw button[data-lang]').forEach(b=>b.classList.toggle('on',b.dataset.lang===LANG));
  document.documentElement.setAttribute('data-modo',MODO); $$('.modesw button').forEach(b=>{ const on=b.dataset.vista===MODO; b.classList.toggle('on',on); b.setAttribute('aria-pressed',on); });
  $('#lblProd').textContent=T('Productor','Producer'); $('#lblCien').textContent=T('Científico','Scientist'); $('#brandSub').textContent=T('· lo que está tejido junto','· what is woven together');
  document.documentElement.classList.toggle('modo-ejemplo', EJ); franjaEjemplo();
  const b=B(S.bloque)||BLOQUES[0];
  if(BLOQUES_RESULTADO.includes(b.id) && !actividades().length) renderVacio($('#main'), b.id);
  else { b.render()($('#main')); ponerRegenRiesgo(b.id, $('#main')); ponerRevisado(b.id, $('#main')); }
  ponerEjemplo(b.id, $('#main')); enlazarAnterior($('#main')); enlazarTips($('#main'));
  $('#pie').innerHTML=`<svg style="width:26px;height:26px;vertical-align:middle;margin-right:6px"><use href="#i-logo"/></svg><b>Ratio Viña</b> ${CONFIG.version} · Ratio Complexus · ${esc(CONFIG.autores)} · ${CONFIG.anio}<br><span class="tiny">${T('Herramienta de apoyo a la decisión: los resultados dependen de los datos capturados. Licencia MIT.','Decision-support tool: results depend on the data entered. MIT licence.')} · <a href="https://hectortecumshe-ai.github.io/">hectortecumshe-ai.github.io</a></span>`;
  renderNav(); actualizarPill(); renderAyuda(); }
function irA(id){ S.visitados[S.bloque]=true; S.bloque=id; guardar(); render(); scrollTo({top:0,behavior:'smooth'}); }
document.addEventListener('click',e=>{ const t=e.target.closest('[data-ir]'); if(t) irA(t.dataset.ir); });
function ponerModo(m){ MODO=m==='cien'?'cien':'prod'; try{ localStorage.setItem('vina_modo',MODO); }catch(e){} render();
  toast(MODO==='cien'?T('Vista científica: estadística, fórmulas y validación','Scientist view: statistics, formulas and validation'):T('Vista productor: lo esencial, en lenguaje sencillo','Producer view: the essentials in plain language')); }
document.addEventListener('click',e=>{ const t=e.target.closest('[data-vista]'); if(t) ponerModo(t.dataset.vista); });
$$('.langsw button[data-lang]').forEach(b=>b.addEventListener('click',()=>{ LANG=b.dataset.lang; try{ localStorage.setItem('vina_lang',LANG); }catch(e){} render(); toast(LANG==='en'?'English':'Español'); }));
function aplicarTema(t){ if(t) document.documentElement.setAttribute('data-theme',t); else document.documentElement.removeAttribute('data-theme');
  const dark=t?t==='dark':matchMedia('(prefers-color-scheme: dark)').matches; $('#btnTema').textContent=dark?'☾':'☀'; }
$('#btnTema').addEventListener('click',()=>{ const cur=document.documentElement.getAttribute('data-theme')||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'); const nt=cur==='dark'?'light':'dark'; aplicarTema(nt); try{ localStorage.setItem('vina_tema',nt); }catch(e){} });
$('#btnAyuda').addEventListener('click',()=>{ const d=$('#dlgAyuda'); if(d.showModal) d.showModal(); });
try{ aplicarTema(localStorage.getItem('vina_tema')); }catch(e){ aplicarTema(null); }
(function(){ const sp=document.querySelector('svg defs'); if(!sp) return; const sym=document.createElementNS('http://www.w3.org/2000/svg','symbol'); sym.setAttribute('id','i-mapa'); sym.setAttribute('viewBox',`0 0 ${MAPA_MX.w} ${MAPA_MX.h}`);
  const regDe=Object.fromEntries(TERR.estados.map(e=>[e[5],e[3]])); sym.innerHTML=Object.entries(MAPA_MX.edo).map(([k,d])=>`<path d="${d}" fill="${(REG_BX[regDe[k]]||{col:'#9cbf5a'}).col}" stroke="#fffaf0" stroke-width="3"/>`).join(''); sp.parentNode.appendChild(sym); })();
S = cargar();
/* Enlace directo a un bloque: #informe, #prospectiva/cien, #tablero/prod/en */
function aplicarHash(){ const h=decodeURIComponent(location.hash.slice(1)).split('/'); if(h[0]&&BLOQUES.some(b=>b.id===h[0])) S.bloque=h[0]; if(h[1]==='cien'||h[1]==='prod') MODO=h[1]; if(h[2]==='en'||h[2]==='es') LANG=h[2]; }
aplicarHash();
addEventListener('hashchange',()=>{ aplicarHash(); render(); scrollTo(0,0); });
/* Impresión: siempre en tema claro y con el marco teórico desplegado */
let _temaPrevio=null, _cerrados=[];
addEventListener('beforeprint',()=>{ _temaPrevio=document.documentElement.getAttribute('data-theme'); document.documentElement.setAttribute('data-theme','light');
  _cerrados=$$('.teoria details:not([open])'); _cerrados.forEach(d=>d.open=true); });
addEventListener('afterprint',()=>{ if(_temaPrevio) document.documentElement.setAttribute('data-theme',_temaPrevio); else document.documentElement.removeAttribute('data-theme'); _cerrados.forEach(d=>d.open=false); _cerrados=[]; });
render();
